package com.sky.controller.admin;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.mockito.Mockito.doNothing;
import static org.mockito.Mockito.verify;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import com.sky.result.Result;
import com.sky.service.CategoryService;

@ExtendWith(MockitoExtension.class)
class CategoryControllerTest {

    @InjectMocks
    private CategoryController categoryController;

    @Mock
    private CategoryService categoryService;

    @Test
    @DisplayName("正向测试：验证修复后的方法在正常输入下能正确工作")
    void testStartOrStop_normalInput_shouldSucceed() {
        // Arrange
        Integer status = 1;
        Long id = 1L;
        doNothing().when(categoryService).startOrStop(status, id);

        // Act
        Result<String> result = categoryController.startOrStop(status, id);

        // Assert
        assertNotNull(result);
        verify(categoryService).startOrStop(status, id);
    }

    @Test
    @DisplayName("边界测试：验证原来导致异常的输入现在不再抛出异常（id作为请求参数）")
    void testStartOrStop_withIdAsRequestParam_shouldNotThrowException() {
        // Arrange: 修复后，id是@RequestParam，单元测试中直接提供参数值，模拟请求参数存在
        Integer status = 0;
        Long id = 2L;
        doNothing().when(categoryService).startOrStop(status, id);

        // Act & Assert: 调用方法，验证不抛出MissingPathVariableException或其他异常
        assertDoesNotThrow(() -> categoryController.startOrStop(status, id));
        verify(categoryService).startOrStop(status, id);
    }

    @Test
    @DisplayName("空值/null处理：验证当status为null时，方法仍能正常调用服务")
    void testStartOrStop_withNullStatus_shouldHandleGracefully() {
        // Arrange
        Integer status = null;
        Long id = 3L;
        doNothing().when(categoryService).startOrStop(status, id);

        // Act
        Result<String> result = categoryController.startOrStop(status, id);

        // Assert
        assertNotNull(result);
        verify(categoryService).startOrStop(status, id);
    }

    @Test
    @DisplayName("空值/null处理：验证当id为null时，方法仍能正常调用服务")
    void testStartOrStop_withNullId_shouldHandleGracefully() {
        // Arrange
        Integer status = 1;
        Long id = null;
        doNothing().when(categoryService).startOrStop(status, id);

        // Act
        Result<String> result = categoryController.startOrStop(status, id);

        // Assert
        assertNotNull(result);
        verify(categoryService).startOrStop(status, id);
    }
}
